(()=>{'use strict';
const STORE='berry-weekly-scoreboard-v1',LEGACY='calendar_score_app_state',CLOUD_KEY='weekly-scoreboard-v1';
const $=s=>document.querySelector(s),todayKey=()=>key(new Date());
const TYPES={exact50:'剛好50分轉入',excess100:'超過100分超額',parentBonus:'家長額外獎勵'};
const DEFAULT_RULES=['週期：每週五至下週四為一個計分週期。','結算期限：每週結束後的週六12:00前完成結算。','每日加扣分須經家長確認後登記。','每週總分51至99分：取得零食資格，零食額度依實際分數計算。','每週剛好50分：不能購買零食，50分全數轉入長期累計積分。','每週100分：可兌換100元零食。','每週超過100分：零食額度以100元為上限，超過100分的部分轉入長期累計積分。','每週未滿50分：不具備零食購買資格。','逾期至週六12:00仍未結算：該週扣20分，系統自動完成結算。','家長可另外新增獎勵積分；兌換扣除時需選擇積分來源。'];
let state,mode='week',weekStart=cycleFriday(new Date()),monthDate=new Date(new Date().getFullYear(),new Date().getMonth(),1),selectedDate=todayKey(),client=null,user=null,uploadTimer=null,uploadQueue=Promise.resolve(),modalReturnFocus=null;
function key(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function parse(k){const a=k.split('-').map(Number);return new Date(a[0],a[1]-1,a[2],12)}
function plus(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x}
function cycleFriday(d){const x=new Date(d);const offset=(x.getDay()+2)%7;x.setDate(x.getDate()-offset);x.setHours(0,0,0,0);return x}
function startForDate(k){return cycleFriday(parse(k))}
function blank(){return {version:1,trackingStartedAt:key(cycleFriday(new Date())),resetAt:null,records:{},settlements:{},ledger:[],rules:DEFAULT_RULES.slice()}}
function readLocal(){try{return JSON.parse(localStorage.getItem(STORE)||'null')}catch(e){return null}}
function normalize(x){const s=blank();if(!x||typeof x!=='object')return s;s.trackingStartedAt=/^\d{4}-\d{2}-\d{2}$/.test(x.trackingStartedAt||'')?x.trackingStartedAt:s.trackingStartedAt;s.resetAt=x.resetAt&&Number.isFinite(Date.parse(x.resetAt))?new Date(x.resetAt).toISOString():null;s.records=x.records&&typeof x.records==='object'?x.records:{};s.settlements=x.settlements&&typeof x.settlements==='object'?x.settlements:{};s.ledger=Array.isArray(x.ledger)?x.ledger.filter(v=>v&&v.id&&v.category&&Number.isFinite(Number(v.points))):[];s.rules=Array.isArray(x.rules)&&x.rules.length?x.rules:DEFAULT_RULES.slice();return s}
function load(){let x=readLocal();if(x){state=normalize(x);return}const old=(()=>{try{return JSON.parse(localStorage.getItem(LEGACY)||'null')}catch(e){return null}})();state=blank();if(old){state.records=old.records||{};state.settlements=old.settlements||{};const carry=Number(old.accumulatedPoints||0);if(carry>0)state.ledger.push({id:'legacy-carryover-v1',category:'parentBonus',kind:'legacy',points:carry,reason:'舊版累計積分結轉（原始來源未分類）',date:todayKey(),createdAt:new Date().toISOString()});if(Array.isArray(old.rules)&&old.rules.length)state.rules=old.rules;state.trackingStartedAt=Object.keys(state.records).sort()[0]||state.trackingStartedAt}saveLocal()}
function saveLocal(){try{localStorage.setItem(STORE,JSON.stringify(state));return true}catch(e){toast('本機儲存失敗，請檢查瀏覽器儲存空間');return false}}
function balance(category){return state.ledger.filter(x=>!category||x.category===category).reduce((a,x)=>a+Number(x.points||0),0)}
function total(){return balance()}
function escapeHtml(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(s){const n=$('#toast');n.textContent=s;n.hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>n.hidden=true,3000)}
function scheduleUpload(){if(!user||!client)return;clearTimeout(uploadTimer);uploadTimer=setTimeout(()=>uploadCloud().catch(e=>{console.warn(e);$('#syncStatus').textContent='雲端同步失敗｜本機資料已保留'}),700)}
function save(){if(saveLocal())scheduleUpload()}
function merge(a,b){const out=normalize(a);b=normalize(b);const ar=Date.parse(out.resetAt||'')||0,br=Date.parse(b.resetAt||'')||0;if(ar>br)return out;if(br>ar)return b;Object.keys(b.records).forEach(d=>{const map=new Map((out.records[d]||[]).map(r=>[String(r.id),r]));(b.records[d]||[]).forEach(r=>map.set(String(r.id),r));out.records[d]=Array.from(map.values())});Object.keys(b.settlements).forEach(k=>{const old=out.settlements[k],next=b.settlements[k];if(!old||(!old.settled&&next.settled)||(new Date(next.settledAt||0)>new Date(old.settledAt||0)))out.settlements[k]=next});const ledger=new Map(out.ledger.map(x=>[String(x.id),x]));b.ledger.forEach(x=>ledger.set(String(x.id),x));out.ledger=Array.from(ledger.values());if(b.trackingStartedAt<out.trackingStartedAt)out.trackingStartedAt=b.trackingStartedAt;out.rules=b.rules&&b.rules.length?b.rules:out.rules;return out}
async function initCloud(){const c=window.MeihaoSupabaseConfig;if(!c||!window.supabase||!c.publishableKey)return;client=window.supabase.createClient(c.url,c.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});const res=await client.auth.getSession();if(res.error)throw res.error;user=res.data.session&&res.data.session.user;let activeId=user&&user.id||null;if(user)await syncCloud();client.auth.onAuthStateChange((_event,session)=>{const next=session&&session.user||null;const nextId=next&&next.id||null;if(nextId===activeId)return;activeId=nextId;user=next;if(user)syncCloud().catch(e=>{console.warn(e);$('#syncStatus').textContent='雲端同步失敗｜本機資料已保留'});else $('#syncStatus').textContent='未登入｜本機儲存'});if(!user)$('#syncStatus').textContent='未登入｜本機儲存'}
async function syncCloud(){if(!user||!client)return;$('#syncStatus').textContent='雲端同步中…';const q=await client.from('learning_progress').select('state,schema_version').eq('user_id',user.id).eq('progress_key',CLOUD_KEY).maybeSingle();if(q.error)throw q.error;state=merge(state,q.data&&q.data.state);saveLocal();await uploadCloud();$('#syncStatus').textContent='Google帳號｜雲端已同步'}
async function uploadCloud(){if(!user||!client)return;const snapshot=JSON.parse(JSON.stringify(state));uploadQueue=uploadQueue.catch(()=>{}).then(async()=>{const q=await client.from('learning_progress').upsert({user_id:user.id,progress_key:CLOUD_KEY,schema_version:1,state:snapshot},{onConflict:'user_id,progress_key'});if(q.error)throw q.error;$('#syncStatus').textContent='Google帳號｜雲端已同步'});return uploadQueue}
function weekDates(start){return Array.from({length:7},(_,i)=>plus(start,i))}
function recordsForDay(k){return Array.isArray(state.records[k])?state.records[k]:[]}
function weekTotal(start){return weekDates(start).reduce((sum,d)=>sum+recordsForDay(key(d)).reduce((n,r)=>n+Number(r.points||0),0),0)}
function deadline(start){const d=plus(start,8);d.setHours(12,0,0,0);return d}
function weekEnd(start){const d=plus(start,7);d.setHours(0,0,0,0);return d}
function addLedger(id,category,kind,points,reason,weekKey){state.ledger.push({id:id,category:category,kind:kind,points:points,reason:reason,date:todayKey(),weekKey:weekKey||null,createdAt:new Date().toISOString()})}
function settle(start,late){const wk=key(start);if(state.settlements[wk]&&state.settlements[wk].settled)return false;const raw=weekTotal(start),penalty=late?20:0,score=raw-penalty;let transferred=0,snack=0,category=null;if(score===50){transferred=50;category='exact50'}else if(score>100){transferred=score-100;category='excess100';snack=100}else if(score>50){snack=Math.min(score,100)}if(transferred>0)addLedger('settlement-'+wk,category,'weekly_transfer',transferred,category==='exact50'?'週結算剛好50分轉入':'週結算超過100分超額轉入',wk);state.settlements[wk]={settled:true,weeklyTotal:raw,penalty:penalty,adjustedTotal:score,snackMoney:snack,transferred:transferred,settledAt:new Date().toISOString(),late:!!late};save();return true}
function autoSettleOverdue(){const first=cycleFriday(parse(state.trackingStartedAt));const current=cycleFriday(new Date());for(let d=new Date(first);d<current;d=plus(d,7)){if(deadline(d)<=new Date()&&!(state.settlements[key(d)]&&state.settlements[key(d)].settled))settle(d,true)}}
function categoryLabel(c){return TYPES[c]||c}
function renderBalance(){const t=total();$('#headerBalance').textContent=t+' 分';$('#totalBalance').textContent=t;$('#balanceExact').textContent=balance('exact50')+' 分';$('#balanceExcess').textContent=balance('excess100')+' 分';$('#balanceBonus').textContent=balance('parentBonus')+' 分';const rows=state.ledger.slice().sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));$('#ledgerCount').textContent=rows.length+' 筆紀錄';$('#ledgerList').innerHTML=rows.length?rows.slice(0,30).map(x=>'<div class="ledger-row"><div><strong>'+escapeHtml(x.reason)+'</strong><small>'+escapeHtml(x.date)+'｜'+escapeHtml(categoryLabel(x.category))+(x.weekKey?'｜週期 '+escapeHtml(x.weekKey):'')+'</small></div><span class="ledger-points '+(x.points<0?'minus':'')+'">'+(x.points>0?'+':'')+x.points+' 分</span></div>').join(''):'<p class="empty-day">目前沒有累計積分異動紀錄。</p>'}
function renderRules(){$('#rulesList').innerHTML=state.rules.map(x=>'<li>'+escapeHtml(x)+'</li>').join('')}
function dayCard(d){const k=key(d),rs=recordsForDay(k),sum=rs.reduce((n,r)=>n+Number(r.points||0),0),isSelected=k===selectedDate,isToday=k===todayKey(),locked=!!(state.settlements[key(cycleFriday(d))]||{}).settled;let html='<article class="day-card '+(isSelected?'selected ':'')+(isToday?'today':'')+'" data-day="'+k+'"><div class="day-top"><span class="day-date">'+(d.getMonth()+1)+'/'+d.getDate()+'（'+['日','一','二','三','四','五','六'][d.getDay()]+'）</span><span class="day-total '+(sum<0?'negative':'')+'">'+(sum>0?'+':'')+sum+'</span></div><div class="day-records">';html+=rs.length?rs.map(r=>'<div class="day-record '+(r.points<0?'neg':r.points===0?'zero':'')+'"><span>'+escapeHtml(r.reason)+'</span><b>'+(r.points>0?'+':'')+r.points+'</b><button type="button" data-delete="'+k+'" data-id="'+escapeHtml(r.id)+'" aria-label="刪除紀錄">×</button></div>').join(''):'<div class="empty-day">尚無紀錄</div>';html+='</div>'+(locked?'<small class="locked-note">本週已結算</small>':'')+'</article>';return html}
function settlementCard(start){const wk=key(start),s=state.settlements[wk],raw=weekTotal(start),end=weekEnd(start),due=deadline(start),now=new Date(),can=now>=end&&now<due&&!s,score=s?s.adjustedTotal:raw, snack=s?s.snackMoney:(score>50?Math.min(score,100):0),transfer=s?s.transferred:(score===50?50:score>100?score-100:0);let status=s?(s.late?'逾期自動結算':'已完成結算'):(now<end?'週期進行中':now<due?'等待結算':'逾期結算處理中');let note=s?'原始週分 '+s.weeklyTotal+' 分'+(s.penalty?'｜逾期扣 '+s.penalty+' 分':'')+'｜結算分數 '+s.adjustedTotal+' 分':'原始週分 '+raw+' 分｜週六12:00前完成結算';let btn=s?'已完成本週結算':can?'執行本週結算':now<end?'週期尚未結束':'系統將依期限自動結算';return '<article class="settlement-card"><h3>🏆 本週大結算</h3><div class="settlement-score">'+(s?score:raw)+' 分</div><p>'+escapeHtml(status)+'<br>'+escapeHtml(note)+'<br>零食額度：'+snack+' 元<br>轉入長期累計：'+transfer+' 分</p><button type="button" data-settle="'+wk+'" '+(!can?'disabled':'')+'>'+btn+'</button></article>'}
function renderWeek(){const end=plus(weekStart,6);$('#weekHead').lastElementChild.style.display='';$('#periodTitle').textContent=weekStart.getFullYear()+'年 '+(weekStart.getMonth()+1)+'月';$('#periodRange').textContent=(weekStart.getMonth()+1)+'/'+weekStart.getDate()+'～'+(end.getMonth()+1)+'/'+end.getDate()+'（週五～週四）';$('#calendarHeading').textContent='每週紀錄';$('#weekHead').style.display='grid';$('#calendarGrid').className='calendar-grid week-grid';$('#calendarGrid').innerHTML=weekDates(weekStart).map(dayCard).join('')+settlementCard(weekStart)}
function renderMonth(){const first=new Date(monthDate.getFullYear(),monthDate.getMonth(),1),start=cycleFriday(first);$('#weekHead').lastElementChild.style.display='none';$('#periodTitle').textContent=monthDate.getFullYear()+'年';$('#periodRange').textContent=(monthDate.getMonth()+1)+'月月曆';$('#calendarHeading').textContent='月曆紀錄（週五起始）';$('#weekHead').style.display='grid';$('#calendarGrid').className='calendar-grid month-grid';let arr='';for(let i=0;i<42;i++){const d=plus(start,i);arr+='<div class="month-cell '+(d.getMonth()!==monthDate.getMonth()?'other-month':'')+'">'+dayCard(d)+'</div>'}$('#calendarGrid').innerHTML=arr}
function render(){autoSettleOverdue();$('#weekMode').classList.toggle('active',mode==='week');$('#monthMode').classList.toggle('active',mode==='month');$('#selectedDateLabel').textContent='已選日期：'+selectedDate;$('#entryDate').textContent=selectedDate;$('#headerBalance').textContent=total()+' 分';if(mode==='week')renderWeek();else renderMonth();renderBalance();renderRules()}
function addRecord(points,reason){const wk=key(cycleFriday(parse(selectedDate)));if(state.settlements[wk]&&state.settlements[wk].settled){toast('本週已完成結算，不能再修改每日分數。');return}if(!state.records[selectedDate])state.records[selectedDate]=[];state.records[selectedDate].push({id:'r-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),points:Number(points),reason:String(reason),createdAt:new Date().toISOString()});save();render();toast('已登記 '+(points>0?'+':'')+points+' 分')}
function deleteRecord(date,id){const wk=key(cycleFriday(parse(date)));if(state.settlements[wk]&&state.settlements[wk].settled){toast('本週已結算，不能刪除紀錄。');return}state.records[date]=(state.records[date]||[]).filter(r=>String(r.id)!==String(id));if(!state.records[date].length)delete state.records[date];save();render()}
function openModal(type,category){modalReturnFocus=document.activeElement;let title='',body='';if(type==='deduct'){title='扣除累計積分';const c=category||'parentBonus';body='<p>選擇要扣除的積分來源。各來源獨立記帳，不能扣成負數。</p><label>扣除來源</label><select id="modalCategory">'+Object.keys(TYPES).map(k=>'<option value="'+k+'" '+(k===c?'selected':'')+'>'+TYPES[k]+'（可用 '+balance(k)+' 分）</option>').join('')+'</select><label>扣除點數</label><input id="modalPoints" type="number" min="1" step="1" value="10"><label>兌換物品／扣除原因</label><input id="modalReason" maxlength="100" placeholder="例如：兌換玩具、文具">'}else if(type==='reward'){title='新增家長額外獎勵';body='<p>此筆積分會計入「家長額外獎勵」，並留下日期及原因。</p><label>獎勵點數</label><input id="modalPoints" type="number" min="1" step="1" value="5"><label>獎勵原因</label><input id="modalReason" maxlength="100" placeholder="例如：主動整理房間">'}else if(type==='custom'){title=category==='sub'?'自訂每日扣分':'自訂每日加分';body='<label>分數</label><input id="modalPoints" type="number" min="1" step="1" inputmode="numeric" value="5"><label>原因／備註</label><input id="modalReason" maxlength="100" placeholder="輸入原因">'}else if(type==='rules'){title='編輯計分規則';body='<p>每行一條規則，儲存後會更新本頁說明。</p><textarea id="modalRules">'+escapeHtml(state.rules.join('\n'))+'</textarea>'}$('#modalRoot').innerHTML='<div class="modal-backdrop" id="modalBackdrop"><form class="modal" id="scoreForm" role="dialog" aria-modal="true" aria-labelledby="scoreModalTitle"><h2 id="scoreModalTitle">'+title+'</h2>'+body+'<div class="modal-actions"><button class="cancel" type="button" data-action="close-modal">取消</button><button class="confirm" type="submit">確認</button></div></form></div>';$('#scoreForm').dataset.type=type;$('#scoreForm').dataset.mode=category||'';const first=$('#scoreForm').querySelector('input,select,textarea,button');if(first)first.focus()}
function closeModal(){$('#modalRoot').innerHTML='';const target=modalReturnFocus;modalReturnFocus=null;if(target&&target.isConnected&&typeof target.focus==='function')target.focus()}
function submitModal(e){e.preventDefault();const f=e.target&&e.target.closest?e.target.closest('#scoreForm'):null;if(!f||!$('#modalRoot').contains(f))return;const type=f.dataset.type,mode=f.dataset.mode;if(!['rules','deduct','reward','custom'].includes(type)){toast('無法辨識的操作，請重新開啟視窗');return}if(type==='rules'){const area=f.querySelector('#modalRules');const v=area.value.split('\n').map(x=>x.trim()).filter(Boolean);if(!v.length){toast('至少保留一條規則');area.focus();return}state.rules=v;save();closeModal();render();toast('計分規則已更新');return}const pointsInput=f.querySelector('#modalPoints'),reasonInput=f.querySelector('#modalReason');const points=Number(pointsInput.value),reason=reasonInput.value.trim();if(!Number.isInteger(points)||points<=0){toast('請輸入大於0的整數點數');pointsInput.focus();return}if(type==='deduct'){const cat=f.querySelector('#modalCategory').value;if(points>balance(cat)){toast('此類積分不足，不能扣除');pointsInput.focus();return}addLedger('deduct-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),cat,'deduction',-points,reason||'積分兌換');save();closeModal();render();toast('已扣除 '+points+' 分')}else if(type==='reward'){addLedger('bonus-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),'parentBonus','parent_reward',points,reason||'家長額外獎勵');save();closeModal();render();toast('已新增 '+points+' 分家長獎勵')}else if(type==='custom'){const wk=key(cycleFriday(parse(selectedDate)));if(state.settlements[wk]&&state.settlements[wk].settled){toast('本週已完成結算，不能再修改每日分數。');return}addRecord(mode==='sub'?-points:points,reason||(mode==='sub'?'自訂扣分':'自訂加分'));closeModal()}}
function handleClick(e){const b=e.target.closest('button,[data-day]');if(!b)return;if(b.dataset.action){const a=b.dataset.action;if(a==='deduct')openModal('deduct',b.dataset.category);if(a==='reward')openModal('reward');if(a==='custom-add')openModal('custom','add');if(a==='custom-sub')openModal('custom','sub');if(a==='edit-rules')openModal('rules');if(a==='close-modal')closeModal();if(a==='reset'&&confirm('確定重置本機與雲端的周計分板資料？此動作無法復原。')){state=blank();state.resetAt=new Date().toISOString();save();render();toast('周計分板資料已重置')}}if(b.dataset.points!==undefined)addRecord(Number(b.dataset.points),b.dataset.reason);if(b.dataset.delete){e.stopPropagation();if(confirm('確定刪除此筆每日紀錄？'))deleteRecord(b.dataset.delete,b.dataset.id)}if(b.dataset.settle){const start=parse(b.dataset.settle);if(confirm('確認結算 '+b.dataset.settle+' 這一週？結算後不能修改該週每日紀錄。')){if(settle(start,false)){render();toast('本週結算完成')}}}if(b.dataset.day){selectedDate=b.dataset.day;weekStart=cycleFriday(parse(selectedDate));render()}}
function bind(){document.addEventListener('click',handleClick);document.addEventListener('keydown',e=>{if(!$('#scoreForm'))return;if(e.key==='Escape'){e.preventDefault();closeModal();return}if(e.key!=='Tab')return;const items=Array.from($('#scoreForm').querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex=\"-1\"])')).filter(x=>x.offsetParent!==null);if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});$('#weekMode').onclick=()=>{mode='week';render()};$('#monthMode').onclick=()=>{mode='month';render()};$('#prevPeriod').onclick=()=>{if(mode==='week')weekStart=plus(weekStart,-7);else monthDate=new Date(monthDate.getFullYear(),monthDate.getMonth()-1,1);render()};$('#nextPeriod').onclick=()=>{if(mode==='week')weekStart=plus(weekStart,7);else monthDate=new Date(monthDate.getFullYear(),monthDate.getMonth()+1,1);render()};$('#todayBtn').onclick=()=>{weekStart=cycleFriday(new Date());monthDate=new Date(new Date().getFullYear(),new Date().getMonth(),1);selectedDate=todayKey();render()};$('#modalRoot').addEventListener('submit',submitModal);$('#modalRoot').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()})}
load();bind();render();initCloud().then(render).catch(e=>{console.warn('Scoreboard cloud sync unavailable',e);$('#syncStatus').textContent='本機儲存｜雲端尚未同步'});
})();